    store:<><path d="M3 9l2-5h14l2 5M5 13v8h14v-8"/><path d="M3 9a3 3 0 006 0 3 3 0 006 0 3 3 0 006 0M9 21v-6h6v6"/></>,
    bag:<><path d="M5 8h14l-1 13H6z"/><path d="M9 9V6a3 3 0 016 0v3"/></>,
