    folder:<path d="M3 5h6l2 2h10v12a2 2 0 01-2 2H5a2 2 0 01-2-2z"/>,
    user:<><circle cx="12" cy="8" r="4"/><path d="M4 21a8 8 0 0116 0"/></>,
    plus:<><path d="M12 5v14M5 12h14"/></>,
    search:<><circle cx="11" cy="11" r="7"/><path d="M20 20l-4-4"/></>,
    chevron:<path d="M9 18l6-6-6-6"/>,
    down:<path d="M6 9l6 6 6-6"/>,
    arrow:<><path d="M5 12h14M13 6l6 6-6 6"/></>,
    back:<><path d="M19 12H5M11 18l-6-6 6-6"/></>,
    more:<><circle cx="5" cy="12" r="1" fill="currentColor"/><circle cx="12" cy="12" r="1" fill="currentColor"/><circle cx="19" cy="12" r="1" fill="currentColor"/></>,
    edit:<><path d="M12 20h9"/><path d="M16.5 3.5a2.1 2.1 0 013 3L8 18l-4 1 1-4z"/></>,
    eye:<><path d="M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12z"/><circle cx="12" cy="12" r="3"/></>,
    download:<><path d="M12 3v12M7 10l5 5 5-5M4 21h16"/></>,
    upload:<><path d="M12 16V4M7 9l5-5 5 5M4 20h16"/></>,
    check:<path d="M5 12l4 4L19 6"/>,
    clock:<><circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/></>,
    settings:<><circle cx="12" cy="12" r="3"/><path d="M19.4 15a1.7 1.7 0 00.3 1.9l.1.1-2.8 2.8-.1-.1a1.7 1.7 0 00-1.9-.3 1.7 1.7 0 00-1 1.6V21H9v-.1a1.7 1.7 0 00-1-1.6 1.7 1.7 0 00-1.9.3l-.1.1L3.2 17l.1-.1a1.7 1.7 0 00.3-1.9A1.7 1.7 0 002 14H2v-4h.1a1.7 1.7 0 001.6-1 1.7 1.7 0 00-.3-1.9L3.2 7 6 4.2l.1.1a1.7 1.7 0 001.9.3A1.7 1.7 0 009 3V3h4v.1a1.7 1.7 0 001 1.6 1.7 1.7 0 001.9-.3l.1-.1L17.8 7l-.1.1a1.7 1.7 0 00-.3 1.9 1.7 1.7 0 001.6 1H21v4h-.1a1.7 1.7 0 00-1.5 1z"/></>,
    logout:<><path d="M10 4H4v16h6M14 8l4 4-4 4M8 12h10"/></>,
    scissors:<><circle cx="6" cy="7" r="3"/><circle cx="6" cy="17" r="3"/><path d="M8.5 8.5L21 3M8.5 15.5L21 21M12 12l9-4"/></>,
    yarn:<><circle cx="12" cy="12" r="9"/><path d="M5 8c5-2 10 1 14 5M4 13c5-2 10 1 13 5M9 4c0 5 3 10 8 14"/></>,
